import React, { useEffect, useState } from 'react';

import { container } from './PieChartTooltipBody.sty.js';
import { Flex } from '../../../../layouts-core/flex/Flex.js';
import { mergeTooltipActions } from '../../../core/components/series-action/functions/mergeTooltipActions.js';
import { TooltipText } from '../../../core/components/tooltip/section-components/atoms/TooltipText.js';
import { TooltipBody } from '../../../core/components/tooltip/section-components/TooltipBody.js';
import { TooltipInfoContent } from '../../../core/components/tooltip/section-components/TooltipInfoContent.js';
import { TooltipItem } from '../../../core/components/tooltip/section-components/TooltipItem.js';
import { TooltipSymbolContent } from '../../../core/components/tooltip/section-components/TooltipSymbolContent.js';
import { TooltipValueContent } from '../../../core/components/tooltip/section-components/TooltipValueContent.js';
import { useTooltipSeriesActions } from '../../../core/components/tooltip/shared/hooks/useTooltipSeriesActions.js';
import {
  relativeValueItem,
  valueItem,
  valueContainer,
} from '../../../core/components/tooltip/shared/styles/SeriesBasedContent.sty.js';
import { SingleDataPointShape } from '../../../core/components/tooltip-atoms/shapes/SingleDataPointShape.js';
import { TooltipItem as TooltipItemType } from '../../../core/types/tooltip.js';
import { useTruncationMode } from '../../context/FormatterContext.js';
import { useSlicesContext } from '../../context/SlicesContext.js';
import {
  useTooltipContent,
  useTooltipPinnedStatus,
} from '../../hooks/store/selectors.js';
import {
  InternalSliceData,
  type InternalTooltipContent,
} from '../../types/internal/pie-chart.js';

export const PieChartTooltipBody = () => {
  const [tooltipContent, setTooltipContent] = useState<
    InternalTooltipContent | undefined
  >();

  const { slices } = useSlicesContext();

  const isTooltipPinned = useTooltipPinnedStatus();

  const storedTooltipContent = useTooltipContent();

  const truncationMode = useTruncationMode();

  const seriesActions = useTooltipSeriesActions<InternalSliceData>(
    slices,
    (slice) => slice.id,
  );

  useEffect(() => {
    if (!isTooltipPinned && storedTooltipContent) {
      setTooltipContent(storedTooltipContent);
    }
  }, [storedTooltipContent, isTooltipPinned]);

  if (!tooltipContent) {
    return null;
  }

  const tooltipItem: TooltipItemType = {
    id: tooltipContent.id,
    name: tooltipContent.name,
    color: { Default: tooltipContent.color },
    values: [
      tooltipContent.absoluteValue?.toString(),
      tooltipContent.relativeValue?.toString(),
    ],
  };

  const pieActionsCallback = mergeTooltipActions(tooltipItem, seriesActions);

  return (
    <div className={container}>
      <TooltipBody virtualization={false}>
        <TooltipItem actions={pieActionsCallback}>
          <TooltipSymbolContent>
            <SingleDataPointShape color={tooltipContent.color} />
          </TooltipSymbolContent>
          <TooltipInfoContent style={{ maxWidth: 150 }}>
            <TooltipText truncationMode={truncationMode}>
              {tooltipContent.name}
            </TooltipText>
          </TooltipInfoContent>
          <TooltipValueContent>
            <span className={valueContainer} role="row">
              <Flex gap={4} alignItems="center">
                <span className={relativeValueItem}>
                  {`${tooltipContent.relativeValue}%`}
                </span>
                <span className={valueItem}>
                  {tooltipContent.absoluteValue}
                </span>
              </Flex>
            </span>
          </TooltipValueContent>
        </TooltipItem>
      </TooltipBody>
    </div>
  );
};

PieChartTooltipBody['displayName'] = 'PieChartTooltipBody';
